CREATE PROCEDURE p()
BEGIN
  DECLARE done INT DEFAULT 0;
  DECLARE CONTINUE HANDLER FOR NOT FOUND BEGIN SET done = 1; END;
  outer_loop: LOOP
    REPEAT
      SET done = done + 1;
    UNTIL done > 3 END REPEAT;
    CASE done
      WHEN 4 THEN LEAVE outer_loop;
      ELSE SET done = REPEAT('x', 0) + done;
    END CASE;
  END LOOP outer_loop;
END;
CALL p();

